			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack #C000 down (the platform's)"
			DISPLAY "NTC memory: Reserved #BE00-#BFFF (platform zxn)"
			DISPLAY "NTC memory: Reserved #FD00-#FFFF (platform zxn)"
			DISPLAY "NTC memory: Reserved #E000-#F3FF (platform zxn (the text screen))"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 49152) && (ntc_bssfrom + ntc_bss_size > 48640)	; fwdref-ok
ntc_bss		equ 49152		; after Option Memory Reserved #BE00-#BFFF
			ELSEIF (ntc_bssfrom < 62464) && (ntc_bssfrom + ntc_bss_size > 57344)	; fwdref-ok
ntc_bss		equ 62464		; after Option Memory Reserved #E000-#F3FF
			ELSEIF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 64768)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #FD00-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
			ASSERT ntc_bss + ntc_bss_size <= #10000, "out of memory: the arrays (after the last Option Memory Reserved / Paged range) do not fit below #10000"	; fwdref-ok
arr_tbl		equ ntc_bss + 0		; 8 bytes
arr_pool_mslots		equ ntc_bss + 8		; 8 bytes
pa_thirdof_a		equ ntc_bss + 16		; 12 bytes
arr_pool_mslots_used		equ ntc_bss + 28		; 8 bytes
arr_pool_mslots_total		equ ntc_bss + 36		; 8 bytes
arr_pool_mslots_count		equ ntc_bss + 44		; 8 bytes
ntc_bss_size	equ 52
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 48640) || (ntc_bss >= 49152), "the program (or its arrays) reaches into the platform's reserved #BE00-#BFFF (platform zxn: Option Memory Available frees it)"
			ASSERT (ntc_free <= 64768) || (ntc_bss >= 65536), "the program (or its arrays) reaches into the platform's reserved #FD00-#FFFF (platform zxn: Option Memory Available frees it)"
			ASSERT (ntc_free <= 57344) || (ntc_bss >= 62464), "the program (or its arrays) reaches into the platform's reserved #E000-#F3FF (platform zxn (the text screen): Option Memory Available frees it)"

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			IF NTC_PLATRSV == 0		; (with the platform's #BA00-#FFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #BA00, "the program and its arrays must end below #BA00 (the FileSystem class's DOS area is #BA00-#BDFF, the stack #BE00-#BFFF, the screen #C000-#FFFF)"
			ENDIF
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
; DivMMC: its automatic paging and its entry points stay exactly as NextZXOS left them
; (NextRegs #B8-#BB untouched). Until 20261110-2 the stub cut them to "rst 8 with ROM 3"
; (#B8 = 2, #B9 = 0, #BB = 0): every emulator ran that; four games crashed on a real Next
; at their first esxDOS call, and #BB = 0 also cleared bit 6, the 0x1FF8-0x1FFF exit the DOS
; leaves its memory by - the emulators do not model those registers (ZEsarUX ignores them),
; so nothing here can prove it; the DOS's own setting is the one every working NEX runs
; with. NextZXOS's setting traps rst 8
; (and #0038, #3Dxx, the tape entries) only with ROM 3 paged, which a program never has
; except round an esxDOS call (the FileSystem class, CyborgOS's SD drive: ROM 3 in
; slots 0-1, rst 8, ROM 3 off), so nothing pages DivMMC in by accident
; (no out (#E3): DivMMC's memory is already out when a NEX starts - .nexload leaves it so -
; and writing the port selects its RAM bank 0 and drops MAPRAM, which loses NextZXOS's esxDOS
; state: its file handles are in DivMMC RAM. With it untouched, RST 8 calls work from the program
; (automap on, the ROM in slots 0-1 for the call: CyborgOS's SD drive does that)
			ld a, #8E		; the 128K paging: normal mode, ROM 0 (no change to slots 6-7: bit 3 = 0). NextZXOS's
			out (c), a		; DivMMC entry points (rst 8, #0038, #3Dxx, the tape addresses) trap only with ROM 3
			inc b			; selected: with ROM 0 none can, whatever a slot holds; an esxDOS call selects ROM 3
			xor a			; round its rst 8 and puts ROM 0 back (the FileSystem class, CyborgOS's SD drive)
			out (c), a
			dec b
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 3
			out (c), a
			inc b
			ld a, 3
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 0, #51, 1, #52, 2, #54, 4, #55, 5, #56, 10, #57, 11
			SAVENEX OPEN "VBTEST5.NEX", zxn_boot, #BFFE
			SAVENEX CORE 3, 0, 0
			SAVENEX CFG 0
			SAVENEX BANK 5, 2, 0, 1
			SAVENEX CLOSE
